style.css:
@-moz-document regexp(".*") {
:root {
    -bg0: #0f1220;      /* page background */
    -bg1: #151a2e;      /* panels */
    -text: #e9e7ff;     /* text */
    -muted: #b9b6e6;    /* secondary */
    -accent: #9ad7ff;   /* links/buttons */
    -accent2:#ffb3d9;   /* highlights */
    -radius: 16px;
  }

  html, body {
    background: radial-gradient(1000px 600px at 20% 10%, rgba(255,179,217,.18), transparent 60%),
                radial-gradient(900px 650px at 70% 20%, rgba(154,215,255,.16), transparent 60%),
                linear-gradient(180deg, var(--bg0), var(--bg1)) !important;
    color: var(--text) !important;
  }

  /* Make most “card-like” things look consistent */
  div, section, main, article, header, nav, aside, footer {
    border-radius: var(--radius) !important;
  }

  /* Links */
  a, a:visited {
    color: var(--accent) !important;
    text-decoration-thickness: 2px;
  }
  a:hover {
    color: var(--accent2) !important;
  }

  /* Inputs */
  input, textarea, select, button {
    background: rgba(255,255,255,.06) !important;
    color: var(--text) !important;
    border: 1px solid rgba(255,255,255,.12) !important;
    border-radius: 12px !important;
    outline: none !important;
  }

  /* Soft “glass” panel effect for many common containers */
  [class*="card"], [class*="panel"], [class*="container"],
  [class*="content"], [class*="sidebar"], [class*="menu"] {
    background: rgba(255,255,255,.05) !important;
    border: 1px solid rgba(255,255,255,.10) !important;
    backdrop-filter: blur(10px);
  }

  /* Reduce harsh borders */
  hr, [role="separator"] {
    opacity: .25 !important;
  }
}
